          xAxisIndex: 1,
          yAxisIndex: 1,
          renderItem: rangeRenderer,
          data: layer.bins
            .filter((b) => b.count)
            .map((b) => [(b.from + b.to) / 2, b.min, b.max]),
          silent: true,
          clip: true,
        });
      const values: (number | null)[][] = [];
      for (const b of layer.bins) {
        const at =
          view.resolution === data.cadenceMs && b.count === 1
            ? b.firstValidAt!
            : (b.from + b.to) / 2;
        const previous = values.at(-1);
        if (
          view.resolution === data.cadenceMs &&
          previous &&
          previous[1] !== null &&
          at - previous[0]! > data.cadenceMs * 1.5
        )
          values.push([(at + previous[0]!) / 2, null]);
        // Partial buckets remain visible as isolated marks; they never bridge missing observations.
        if (b.covered < b.expected || b.invalid) values.push([b.from, null]);
        values.push([at, b.mean]);
        if (b.covered < b.expected || b.invalid) values.push([b.to - 1, null]);
      }
      const showSamples = layer.bins.length < 100;
      series.push({
        id: `depth-${layer.id}`,
        name: `${layer.depthCm} cm`,
        type: "line",
        xAxisIndex: 1,
        yAxisIndex: 1,
        data: values,
        showSymbol: showSamples,
        showAllSymbol: false,
        symbol: "circle",
        symbolSize: 4,
        endLabel: {
          show: dimensions.width >= 640 && depthIds.length <= 6,
          formatter: `${layer.depthCm} cm`,
          color,
          fontSize: 12 * factor,
          fontFamily: theme.font,
          distance: 8,
        },
        labelLayout: { moveOverlap: "shiftY" },
        lineStyle: {
          color,
          width:
            focusedDepthId === layer.id
              ? 3
              : focusedDepthId || depthIds.length > 8
                ? 1.1
                : 2.2,
          type: dash,
          cap: "round",
          join: "round",
        },
        itemStyle: { color },
        connectNulls: false,
        animation: false,
        silent: true,
        clip: false,
      });
      if (!showSamples) {
        const isolated = values.filter(
          (value, index) =>
            value[1] !== null &&
            (index === 0 || values[index - 1][1] === null) &&
            (index === values.length - 1 || values[index + 1][1] === null),
        );
        if (isolated.length) {
          const marker: CustomSeriesRenderItem = (_p, api) => {
            const point = api.coord([api.value(0), api.value(1)]);
            return {
              type: "circle",
              shape: { cx: point[0], cy: point[1], r: 2 },
              style: { fill: color },
            };
          };
          series.push({
            type: "custom",
            xAxisIndex: 1,
            yAxisIndex: 1,
            renderItem: marker,
            data: isolated,
            silent: true,
            clip: false,
          });
        }
      }
    }
    for (const driver of [
      ...water,
      ...view.drivers.filter((d) => d.id === data.kc?.id),
    ]) {
      const isKc = driver.id === data.kc?.id,
        isRain = driver.id === data.rainfall?.id;
      const gridIndex = isKc ? 3 : 2,
        color = isKc ? theme.kc : isRain ? theme.rain : theme.et0;
      const render: CustomSeriesRenderItem = (_p, api) => {
        const a = api.coord([api.value(0), api.value(2)]),
          b = api.coord([api.value(1), api.value(2)]),
          zero = api.coord([api.value(0), 0]);
        if (isRain)
          return {
            type: "rect",
            shape: {
              x: a[0] + 0.5,
              y: Math.min(a[1], zero[1]),
              width: Math.max(1, b[0] - a[0] - 1),
              height: Math.max(1, Math.abs(zero[1] - a[1])),
            },
            style: {
              fill: echarts.color.modifyAlpha(color, theme.dark ? 0.22 : 0.14)!,
              stroke: color,
              lineWidth: 1,
            },
          };
        return {
          type: "line",
          shape: { x1: a[0], x2: b[0], y1: a[1], y2: b[1] },
          style: { stroke: color, lineWidth: 2, lineDash: isKc ? [] : [5, 3] },
        };
      };
      series.push({
        id: `driver-${driver.id}`,
        type: "custom",
        xAxisIndex: gridIndex,
        yAxisIndex: gridIndex,
        renderItem: render,
        encode: { x: [0, 1], y: 2 },
        data: driver.records
          .filter(
            (r) =>
              r.value !== null &&
              Number.isFinite(r.value) &&
              r.quality !== "bad",
          )
          .map((r) => [
            Math.max(r.from, view.window.from),
            Math.min(r.to, view.window.to),
            r.value,
          ]),
        silent: true,
        clip: true,
      });
    }
    const eventRenderer: CustomSeriesRenderItem = (_p, api) => {
      const a = api.coord([api.value(0), api.value(2)]),
        b = api.coord([api.value(1), api.value(2)]),
        instant = Number(api.value(3));
      const color =
        theme.events[
          Object.keys(eventIndex).find(
            (key) => eventIndex[key as SoilEventKind] === Number(api.value(4)),
          ) ?? "installation"
        ];
      const halfHeight = Math.min(
        5 * factor,
        (plots[4].height / Math.max(1, lanes.length)) * 0.35,
      );
      if (instant)
        return {
          type: "polygon",
          shape: {
            points: [
              [a[0], a[1] - halfHeight],
              [a[0] + halfHeight, a[1]],
              [a[0], a[1] + halfHeight],
              [a[0] - halfHeight, a[1]],
            ],
          },
          style: { fill: color },
        };
      return {
        type: "rect",
        shape: {
          x: a[0],
          y: a[1] - halfHeight,
          width: Math.max(2, b[0] - a[0]),
          height: halfHeight * 2,
          r: Math.min(2, halfHeight),
        },
        style: {
          fill: color,
          opacity: 1,
          stroke: color,
          lineWidth: 1,
          lineDash: api.value(5) ? [3, 2] : [],
        },
      };
    };
    series.push({
      id: "soil-events",
      type: "custom",
      xAxisIndex: 4,
      yAxisIndex: 4,
      renderItem: eventRenderer,
      encode: { x: [0, 1], y: 2 },
      clip: true,
      data: lanes.flatMap((lane, i) =>
        lane.events.map((e) => ({
          value: [
            Math.max(e.from, view.window.from),
            Math.min(
              e.to ?? (e.timing === "instant" ? e.from : view.window.to),
              view.window.to,
            ),
            i,
            e.timing === "instant" ? 1 : 0,
            eventIndex[e.kind],
            e.timing === "interval" && !e.to ? 1 : 0,
          ],
          eventId: e.id,
        })),
      ),
    });
    const option: EChartsOption = {
      animation: false,
      useUTC: true,
      backgroundColor: "transparent",
      textStyle: { fontFamily: theme.font },
      grid: plots.map((p, i) => ({
        left,
        right,
        top: p.top,
        height: p.height,
        show: i === 0 || i === 1,
        borderColor: theme.line,
        borderWidth: 0,
        backgroundColor:
          i === 1
            ? theme.dark
              ? "rgba(255,255,255,.015)"
              : "rgba(0,0,0,.018)"
            : "transparent",
      })),
      xAxis,
      yAxis,
      series,
      tooltip: { show: false, trigger: "axis" },
      axisPointer: { link: [{ xAxisIndex: "all" }], triggerOn: "none" },
    };
    chart.setOption(option, { notMerge: true });
    chart.resize();
    const frame = requestAnimationFrame(() => {
      element.dataset.renderMs = (performance.now() - started).toFixed(1);
      onRendered?.(performance.now() - started);
    });
    let previous = NaN;
    const point = (
      event: { offsetX: number; offsetY: number },
      pinned: boolean,
      eventId?: string,
    ) => {
      if (event.offsetX < left || event.offsetX > chart.getWidth() - right)
        return;
      const rawAt = Number(
        chart.convertFromPixel({ xAxisIndex: 0 }, event.offsetX),
      );
      const at = Math.max(
        view.window.from,
        Math.min(
          view.window.to - 1,
          data.window.from +
            Math.floor((rawAt - data.window.from) / view.resolution) *
              view.resolution,
        ),
      );
      if (!Number.isFinite(at) || (!pinned && at === previous)) return;
      if (cursorCallback.current({ at, pinned, eventId })) {
        previous = at;
        pointerAt.current = at;
      }
    };
    const move = (event: { offsetX: number; offsetY: number }) =>
      point(event, false);
    let eventHit = false;
    const click = (event: { offsetX: number; offsetY: number }) => {
      queueMicrotask(() => {
        if (!eventHit && !chart.isDisposed()) point(event, true);
        eventHit = false;
      });
    };
    const eventClick = (params: unknown) => {
      const p = params as {
        data?: { eventId?: string };
        event?: { offsetX: number; offsetY: number };
      };
      if (p.data?.eventId && p.event) {
        eventHit = true;
        point(p.event, true, p.data.eventId);
      }
    };
    chart.getZr().on("mousemove", move);
    chart.getZr().on("click", click);
    chart.on("click", eventClick);
    return () => {
      cancelAnimationFrame(frame);
      if (!chart.isDisposed()) {
        chart.getZr().off("mousemove", move);
        chart.getZr().off("click", click);
        chart.off("click", eventClick);
      }
    };
  }, [
    data,
    view,
    depthIds,
    focusedDepthId,
    comparisonDomain,
    highlightedEventId,
    themeVersion,
    dimensions.width,
    dimensions.height,
    dimensions.font,
    onRendered,
  ]);

  const highlighted = view.events.find(
    (event) => event.id === highlightedEventId,
  );
  const xPosition = (at: number) =>
    left +
    (dimensions.width - left - right) *
      Math.max(
        0,
        Math.min(
          1,
          (at - view.window.from) / (view.window.to - view.window.from),
        ),
      );
  const cursorBinIndex =
    view.layers[0]?.bins.findIndex(
      (bin) => bin.from <= cursorAt && bin.to > cursorAt,
    ) ?? -1;
  return (
    <div
      ref={host}
      className="soil-water-plots"
      role="group"
      aria-label="土壤水分、气象与事件联动图；左右方向键逐时段查看，Enter 固定读数；原始数据页可核查所有记录"
      tabIndex={0}
      data-cells={view.cellCount}
      data-dense={depthIds.length > 8}
      data-y-min={comparisonDomain.min}
      data-y-max={comparisonDomain.max}
      aria-description={`水分曲线使用${scaleLabel}，${comparisonDomain.min.toFixed(data.precision)} 至 ${comparisonDomain.max.toFixed(data.precision)} ${data.unit}；全深度共用，时间缩放保持不变。`}
      onKeyDown={(event) => {
        if (event.key === "Escape" && !cursorPinned) return;
        if (
          ![
            "ArrowLeft",
            "ArrowRight",
            "Home",
            "End",
            "Enter",
            " ",
            "Escape",
          ].includes(event.key)
        )
          return;
        event.preventDefault();
        const at =
          event.key === "Home"
            ? view.window.from
            : event.key === "End"
              ? view.window.to - view.resolution
              : event.key === "ArrowLeft"
                ? Math.max(
                    view.window.from,
                    pointerAt.current - view.resolution,
                  )
                : event.key === "ArrowRight"
                  ? Math.min(
                      view.window.to - 1,
                      pointerAt.current + view.resolution,
                    )
                  : pointerAt.current;
        pointerAt.current = at;
        cursorCallback.current({
          at,
          pinned: event.key !== "Escape",
          source: "keyboard",
        });
      }}
    >
      <div ref={surface} className="soil-water-canvas" aria-hidden="true" />
      {highlighted && (
        <span
          className="soil-water-event-window"
          data-kind={highlighted.kind}
          data-instant={highlighted.timing === "instant"}
          aria-hidden="true"
          style={{
            top: plots[0].top,
            height: plots[4].top + plots[4].height - plots[0].top,
            left: xPosition(highlighted.from),
            width: Math.max(
              1,
              xPosition(
                highlighted.to ??
                  (highlighted.timing === "instant"
                    ? highlighted.from
                    : view.window.to),
              ) - xPosition(highlighted.from),
            ),
            borderLeftWidth:
              highlighted.from < view.window.from ? 0 : undefined,
            borderRightWidth:
              !highlighted.to || highlighted.to > view.window.to
                ? 0
                : undefined,
          }}
        />
      )}
      {view.layers.map((layer, index) => {
        const bin = layer.bins[cursorBinIndex];
        if (!depthIds.includes(layer.id) || bin?.mean == null) return null;
        const sampleAt =
          view.resolution === data.cadenceMs && bin.count === 1
            ? bin.firstValidAt!
            : (bin.from + bin.to) / 2;
        return (
          <span
            key={layer.id}
            className="soil-water-cursor-point"
            aria-hidden="true"
            style={{
              left: xPosition(sampleAt),
              top:
                plots[1].top +
                plots[1].height *
                  (1 -
                    (bin.mean - comparisonDomain.min) /
                      (comparisonDomain.max - comparisonDomain.min)),
              color: `var(--soil-series-${Math.floor(index / 4) % 5})`,
            }}
          />
        );
      })}
      {trackLabels.map((track, i) => (
        <div
          key={track.key}
          className="soil-water-track-label"
          data-track={track.key}
          style={{
            top: plots[i].top,
            height: plots[i].height,
            width: 40 * factor,
          }}
          aria-hidden="true"
        >
          <span>{track.label}</span>
          <small>{track.unit}</small>
        </div>
      ))}
      <span
        className="soil-water-crosshair"
        aria-hidden="true"
        style={{
          top: plots[0].top,
          height: plots[4].top + plots[4].height - plots[0].top,
          left:
            left +
            (dimensions.width - left - right) *
              Math.max(
                0,
                Math.min(
                  1,
                  ((Number.isFinite(cursorAt) ? cursorAt : view.window.from) -
                    view.window.from) /
                    (view.window.to - view.window.from),
                ),
              ),
        }}
      />
    </div>
  );
});

export const SoilWaterNavigator = memo(function SoilWaterNavigator({
  data,
  window,
  onWindow,
}: {
  data: PreparedSoil;
  window: SoilWindow;
  onWindow: (window: SoilWindow) => void;
}) {
  const host = useRef<HTMLDivElement>(null),
    instance = useRef<echarts.ECharts | null>(null),
    callback = useRef(onWindow);
  callback.current = onWindow;
  const version = useChartTheme(host);
  useEffect(() => {
    if (!host.current) return;
    const chart = echarts.init(host.current, undefined, { renderer: "canvas" });
    instance.current = chart;
    const resize = new ResizeObserver(() => {
      if (!chart.isDisposed()) chart.resize();
    });
    resize.observe(host.current);
    chart.on("datazoom", () => {
      const option = chart.getOption() as {
        dataZoom: { start: number; end: number }[];
      };
      const { start, end } = option.dataZoom[0],
        span = data.window.to - data.window.from;
      callback.current({
        from:
          data.window.from +
          Math.round((span * start) / 100 / data.cadenceMs) * data.cadenceMs,
        to:
          data.window.from +
          Math.round((span * end) / 100 / data.cadenceMs) * data.cadenceMs,
      });
    });
    return () => {
      resize.disconnect();
      chart.dispose();
      instance.current = null;
    };
  }, [data]);
  useEffect(() => {
    const chart = instance.current;
    if (!chart || !host.current) return;
    const theme = themeOf(host.current),
      span = data.window.to - data.window.from;
    const bins = binSoilRecords(
      data.depths[0]?.records ?? [],
      data.window,
      Math.max(SOIL_DAY, data.cadenceMs),
      data.cadenceMs,
      data.window.from,
    );
    chart.setOption(
      {
        animation: false,
        useUTC: true,
        grid: { left: 8, right: 8, top: 0, bottom: 0 },
        xAxis: {
          type: "time",
          min: data.window.from,
          max: data.window.to,
          show: false,
        },
        yAxis: {
          type: "value",
          show: false,
          min: data.scale.min,
          max: data.scale.max,
        },
        series: [
          {
            type: "line",
            data: bins.map((b) => [
              (b.from + b.to) / 2,
              b.covered === b.expected ? b.mean : null,
            ]),
            showSymbol: false,
            lineStyle: { opacity: 0 },
            silent: true,
          },
        ],
        dataZoom: [
          {
            type: "slider",
            xAxisIndex: 0,
            start: ((window.from - data.window.from) / span) * 100,
            end: ((window.to - data.window.from) / span) * 100,
            minValueSpan: data.cadenceMs,
            realtime: false,
            brushSelect: true,
            top: 8,
            bottom: 4,
            left: 8,
            right: 8,
            showDetail: false,
            borderColor: "transparent",
            fillerColor:
              echarts.color.modifyAlpha(theme.colors[0], 0.12) ||
              "rgba(119,181,248,.12)",
            handleSize: "100%",
            handleStyle: { color: theme.colors[0], borderWidth: 0 },
            moveHandleSize: 6,
            moveHandleStyle: { color: theme.muted },
            dataBackground: {
              lineStyle: { color: theme.muted, opacity: 0.6 },
              areaStyle: { color: theme.muted, opacity: 0.1 },
            },
            selectedDataBackground: {
              lineStyle: { color: theme.colors[0] },
              areaStyle: { color: theme.colors[0], opacity: 0.15 },
            },
          },
        ],
      },
      { notMerge: true, silent: true },
    );
  }, [data, window, version]);
  return <div className="soil-water-navigator" ref={host} aria-hidden="true" />;
});

